<?php
declare(strict_types=1);require_once __DIR__.'/common.php';require_once __DIR__.'/noa-bridge/storage.php';
header('Content-Type: text/html; charset=utf-8');header('Cache-Control: private, no-store');
if(empty($is_member)||($is_admin??'')!=='super'){http_response_code(403);exit('최고관리자 로그인이 필요합니다.');}
function noa_theme_e(string $v):string{return htmlspecialchars($v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$history=[];$error=false;
try{$db=noa_bridge_pdo();$q=$db->query("SELECT revision,payload,changed_at FROM noa_document_history WHERE doc_key='ui:policy' ORDER BY revision DESC LIMIT 30");$history=$q->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){$error=true;}
?><!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>테마 관리 | NOA STUDIO</title><link rel="stylesheet" href="/noa-ui.css?v=20261022-recovery1"><script src="/noa-brand.js?v=20261021-brand1" defer></script><script src="/noa-ui.js?v=20261022-recovery1" defer></script></head><body class="noa-page"><main><p class="noa-eyebrow">NOA STUDIO / ADMINISTRATOR</p><h1>테마 정책과 변경 이력</h1><p class="noa-muted">현재 그누보드 테마: <?=noa_theme_e((string)($config['cf_theme']??''))?> · 신규 전용 테마: noa_studio</p><p>기존 테마 활성화와 게시판·회원 스킨 설정을 보존하고 공통 스타일을 적용합니다. 전용 테마 활성화 전 회원·게시판 쓰기 기능 검증이 필요합니다.</p><form id="policy"><div class="noa-settings-row"><label>관리자 기본 테마<select id="default-theme" required></select></label><fieldset id="enabled-themes"><legend>사용자 선택 허용</legend></fieldset></div><button class="noa-button" type="submit" id="policy-save" disabled>정책 저장</button></form><p id="policy-status" role="status">설정을 불러오는 중입니다.</p><h2>테마 정책 변경 이력</h2><?php if($error):?><p>이력을 불러오지 못했습니다.</p><?php elseif(!$history):?><p class="noa-muted">저장된 변경 이력이 없습니다.</p><?php else:?><ol><?php foreach($history as $item):?><li>Revision <?= (int)$item['revision']?> · <?=noa_theme_e((string)$item['changed_at'])?><pre><?=noa_theme_e((string)$item['payload'])?></pre></li><?php endforeach;?></ol><?php endif;?>
<h2>그누보드 통합 상태</h2><p>코어 인증·CSRF·글쓰기·댓글·첨부파일 처리를 그대로 사용합니다. 기존 기본 테마와 스킨은 삭제하지 않습니다.</p><a class="noa-button" href="/adm/theme.php">그누보드 테마 관리</a><a class="noa-button" href="/adm/board_list.php">게시판·스킨 관리</a></main><script>
(async()=>{const form=document.getElementById('policy'),select=document.getElementById('default-theme'),enabled=document.getElementById('enabled-themes'),status=document.getElementById('policy-status'),save=document.getElementById('policy-save');let remote;try{const[config,r]=await Promise.all([fetch('/noa-design.json').then(r=>r.json()),fetch('/noa-bridge/ui-preferences.php').then(r=>r.json())]);remote=r;if(!r.admin)throw Error();for(const t of config.themes){const option=document.createElement('option');option.value=t.id;option.textContent=t.name;select.append(option);const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.name='enabled';input.value=t.id;input.checked=r.defaults.enabled.includes(t.id);label.append(input,document.createTextNode(t.name));enabled.append(label);}select.value=r.defaults.theme;status.textContent='원본 디자인 설정과 기존 사용자 설정은 보존됩니다.';form.onchange=()=>save.disabled=false;form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{const response=await fetch('/noa-bridge/ui-preferences.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-NOA-CSRF':remote.csrf},body:JSON.stringify({scope:'policy',expectedRevision:remote.policyRevision,settings:{theme:select.value,enabled:[...form.querySelectorAll('input:checked')].map(x=>x.value)}})});const j=await response.json();if(!response.ok)throw Error();remote.policyRevision=j.revision;status.textContent='테마 정책을 저장했습니다. 변경 이력은 다시 열면 표시됩니다.';}catch{save.disabled=false;status.textContent='정책을 저장하지 못했습니다. 기본 테마가 허용 목록에 포함되어 있는지 확인해 주세요.';}};}catch{status.textContent='관리자 설정을 불러오지 못했습니다.';}})();
</script></body></html>
